import dev.wowforever.app.ui.*;
import dev.wowforever.app.ui.journal.*;
import java.awt.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.prefs.Preferences;
import javax.swing.*;

/** Actual source-only Main -> explicitly selected provider download/build -> explicit Open, isolated user storage. */
public final class ProductionSetupJobAcceptance {
 static final java.util.List<String> report=new ArrayList<>();static Path out;static long maxProbe;
 static void check(boolean yes,String label){if(!yes)throw new AssertionError(label);report.add("PASS: "+label);System.out.println("PASS: "+label);}
 static <T>T bounded(JournalSnapshots.Read<T> read)throws Exception{FutureTask<T> task=new FutureTask<>(read::get);SwingUtilities.invokeLater(task);try{return task.get(5,TimeUnit.SECONDS);}catch(TimeoutException stalled){throw new AssertionError("Production EDT did not respond within5s; progress flood or blocked UI",stalled);}}
 static boolean exists(String name)throws Exception{return bounded(()->FirstRunSetupAcceptance.panel()!=null&&JournalSnapshots.all(FirstRunSetupAcceptance.panel()).stream().anyMatch(c->name.equals(c.getName())));}
 static boolean enabled(String name)throws Exception{return bounded(()->FirstRunSetupAcceptance.namedUnchecked(name,AbstractButton.class).isEnabled());}
 static void click(String name)throws Exception{FirstRunSetupAcceptance.click(FirstRunSetupAcceptance.named(name,AbstractButton.class));}
 static String text()throws Exception{return bounded(()->JournalSnapshots.texts(FirstRunSetupAcceptance.panel()));}
 static void waitFor(ResearchAcceptance.Condition condition,long seconds,String label)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(seconds);while(System.nanoTime()<end){if(condition.ready())return;Thread.sleep(200);}throw new AssertionError("Timed out: "+label+"; current setup: "+text());}
 public static void main(String[] args)throws Exception{
  out=Path.of(args[1]);Files.createDirectories(out);try(var files=Files.list(out)){if(files.findAny().isPresent())throw new IllegalArgumentException("Output must be empty");}FirstRunSetupAcceptance.out=out;JournalSnapshots.out=out;report.add("Exact JAR SHA256: "+JournalSnapshots.hash(Path.of(args[0])));report.add("GENUINE PRODUCTION Main/no-DB first-run, isolated fresh XDG/prefs; explicitly selected Questie/native/Wago/Raidbots; Atlas/ATT/VMaNGOS/collector off. Real provider network/build, no authored service injection. Map/media parity is not claimed.");int exit=0;
  try{
   check(System.getProperty("wowforever.database")==null&&System.getProperty("wowforever.data.dir")==null,"No database or reviewed-data override supplied");check(dev.wowforever.app.Main.class.getResource("/data/wowforever.sqlite")==null,"Exact source-only artifact has no bundled database");check(Preferences.userRoot().node("/dev/wowforever/app/db").get("database-path","").isBlank(),"Fresh preferences have no previous database");Path data=Path.of(System.getenv("XDG_DATA_HOME"));try(var files=Files.walk(data)){check(files.noneMatch(Files::isRegularFile),"Isolated XDG data starts empty");}
   ThemeManager.apply(ThemeManager.Mode.DARK);dev.wowforever.app.Main.main(new String[0]);ResearchAcceptance.until(()->JournalSnapshots.edt(FirstRunSetupAcceptance::panel)!=null,"actual production first-run workspace");FirstRunSetupAcceptance.robot=new Robot();FirstRunSetupAcceptance.robot.setAutoDelay(45);JournalSnapshots.robot=FirstRunSetupAcceptance.robot;JournalSnapshots.edt(()->{SwingUtilities.getWindowAncestor(FirstRunSetupAcceptance.panel()).setBounds(20,20,1280,900);return null;});
   FirstRunSetupAcceptance.wizard(2);FirstRunSetupAcceptance.checked("setup-source-questie",true);FirstRunSetupAcceptance.checked("setup-source-native",true);FirstRunSetupAcceptance.checked("setup-source-wago",true);FirstRunSetupAcceptance.checked("setup-source-raidbots-hotfix",true);for(String source:java.util.List.of("atlas","att","vmangos","collector"))FirstRunSetupAcceptance.checked("setup-source-"+source,false);FirstRunSetupAcceptance.snap("production-selected-sources");FirstRunSetupAcceptance.wizard(4);check(exists("setup-review-requirements"),"Production setup exposes real reviewed requirements adapter");FirstRunSetupAcceptance.snap("production-review-before-check");click("setup-review-requirements");waitFor(()->exists("setup-build-library")&&enabled("setup-build-library"),120,"production requirements review ready");check(text().contains("Map pictures")&&text().contains("not imported yet"),"Reviewed first-library scope explicitly discloses missing map/media/collector parity");report.add("PRODUCTION REVIEW: "+text());FirstRunSetupAcceptance.snap("production-reviewed-requirements");
   long start=System.nanoTime();click("setup-build-library");var observed=new LinkedHashSet<String>();long end=System.nanoTime()+TimeUnit.MINUTES.toNanos(10);
   while(System.nanoTime()<end&&!exists("setup-open-built-library")){
    String current=text();if(current.contains("The library needs attention")||current.contains("Stopped safely"))throw new AssertionError("Production job did not reach READY: "+current);
    for(String phase:java.util.List.of("Download selected sources","Prepare library","Build catalogue","Check data","Reduce library size","Open library"))if(current.contains("→ "+phase)&&observed.add(phase)){System.out.println("PRODUCTION PHASE: "+phase);report.add("PRODUCTION PHASE: "+phase);FirstRunSetupAcceptance.snap("production-phase-"+observed.size());}
    long probe=System.nanoTime();bounded(()->true);maxProbe=Math.max(maxProbe,System.nanoTime()-probe);Thread.sleep(250);
   }
   check(exists("setup-open-built-library"),"Actual selected-provider job reaches READY before explicit Open");report.add("Actual build elapsed seconds: "+(System.nanoTime()-start)/1e9);report.add("Max sampled EDT round-trip ms during actual build: "+maxProbe/1e6);report.add("PRODUCTION READY: "+text());check(JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(Window::isShowing).flatMap(window->JournalSnapshots.all(window).stream()).noneMatch(JournalHomePage.class::isInstance)),"Production READY does not automatically activate the library");for(int width:new int[]{1280,420}){JournalSnapshots.edt(()->{SwingUtilities.getWindowAncestor(FirstRunSetupAcceptance.panel()).setSize(width,900);return null;});FirstRunSetupAcceptance.snap("production-ready-"+width);}
   click("setup-open-built-library");waitFor(()->JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(Window::isShowing).flatMap(window->JournalSnapshots.all(window).stream()).anyMatch(c->c instanceof JournalHomePage)),90,"actual generated library opens Journal Home");JournalSnapshots.frame=JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(window->window instanceof MainFrame&&window.isShowing()).map(MainFrame.class::cast).findFirst().orElseThrow());check(true,"Explicit Open validates generated candidate and opens actual Main Journal Home");for(int width:new int[]{1280,420}){JournalSnapshots.edt(()->{JournalSnapshots.frame.setSize(width,900);return null;});JournalSnapshots.snap("production-generated-home-"+width);}
   try(var files=Files.walk(data)){for(Path database:files.filter(file->file.getFileName().toString().endsWith(".sqlite")).toList())report.add("Actual generated database: "+database+"; bytes="+Files.size(database)+"; SHA256="+JournalSnapshots.hash(database));}
  }catch(Throwable failure){report.add("FAIL: "+failure);failure.printStackTrace();exit=1;}finally{Files.write(out.resolve("report.txt"),report);System.out.println(String.join("\n",report));}System.exit(exit);
 }
}
